INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Emperor Go-Hanazono$b$, DATE '1419-07-10', DATE '1471-01-18', $b$Emperor Go-Hanazono (後花園天皇, Go-Hanazono-tennō) (July 10, 1419 – January 18, 1471) was the 102nd emperor of Japan, according to the traditional order of succession. His reign spanned the years from 1428 through 1464.

