INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Emperor Go-Horikawa$b$, DATE '1212-03-22', DATE '1234-08-31', $b$Emperor Go-Horikawa (後堀河天皇, Go-Horikawa-tennō) (22 March 1212 – 31 August 1234), was the 86th emperor of Japan who reigned during the Jōō period, according to the traditional order of succession. His reign spanned the years from 1221 through 1232.

