INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place, birth_precision, death_precision) VALUES (gen_random_uuid(), $b$Emperor Junnin$b$, DATE '0733-01-01', DATE '0765-11-10', $b$Emperor Junnin (淳仁天皇, Junnin-tennō; 733 – November 10, 765) was the 47th emperor of Japan, according to the traditional order of succession. The seventh son of Prince Toneri and a grandson of Emperor Tenmu, his reign spanned the years 758 to 764.

